// Object docs: generated by scripts/pd-docs.mjs from Pd's help patches (BSD-3) and hvcc's
// supported-objects table. Loaded lazily (≈100 KB) the first time the editor needs them.
import { emit } from "../state.js";

let docs = null, loading = null;

export function loadDocs() {
  loading ??= import("./docs.json").then(m => { docs = m.default; emit("docs"); return docs; });
  return loading;
}

const ALIAS = { f: "float", i: "int", b: "bang", t: "trigger", del: "delay", sel: "select", s: "send", r: "receive" };
/** Docs for an object class, or null (also null until loadDocs() resolved). */
export const docFor = cls => docs && cls ? docs[cls] ?? docs[ALIAS[cls]] ?? null : null;
export const docsMeta = () => docs?._meta ?? {};

export const HVCC_DOCS = "https://wasted-audio.github.io/hvcc/reference/objects/supported/";
/** In-app help: opens the editor in a new tab with the official help patch loaded. */
export const helpPageUrl = file => `${location.pathname}?help=${encodeURIComponent(file)}`;
export const helpSourceUrl = file =>
  `https://github.com/pure-data/pure-data/blob/${docsMeta().pdCommit || "master"}/doc/5.reference/${encodeURIComponent(file)}`;
/** Only files the generator copied to public/help/ may be opened. */
export const isHelpFile = name => /^[\w~.+\-&|=<>!%*]+(-help)?\.pd$/.test(name) && !name.includes("..");
